174	/// Output shapes for session-start hooks.
175	#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
176	pub enum BriefingFormat {
177	    /// Plain text: Claude Code, Codex and Kiro add stdout to context.
178	    Text,
179	    /// The full recall outcome.
180	    Json,
181	    /// hookSpecificOutput.additionalContext with hookEventName (Claude Code JSON, VS Code Copilot).
182	    Claude,
183	    /// Gemini CLI: JSON only, hookSpecificOutput.additionalContext.
184	    Gemini,
185	    /// Cursor sessionStart: additional_context.
186	    Cursor,
187	    /// GitHub Copilot CLI sessionStart: additionalContext.
188	    Copilot,
189	    /// Cline TaskStart: contextModification.
190	    Cline,
191	}
