193	/// `[memory]` from an explicit config, else ./leviathan.toml when present.
194	pub fn memory_config(explicit: Option<&Path>) -> Result<MemoryConfig> {
195	    let path = explicit.map(Path::to_path_buf).or_else(|| {
196	        std::env::var_os("LEVIATHAN_CONFIG")
197	            .map(PathBuf::from)
198	            .or_else(|| Path::new(DEFAULT_FILE).exists().then(|| PathBuf::from(DEFAULT_FILE)))
199	    });
200	    let cfg = match path {
201	        Some(p) => Config::load(&p)?.memory,
202	        None => MemoryConfig::default(),
203	    };
204	    Ok(cfg)
205	}
206	
207	/// `--memory=PATH`, else `[memory].path`, else the default location.
208	pub fn resolve_path(flag: Option<&str>, cfg: &MemoryConfig) -> PathBuf {
209	    match flag.map(str::trim).filter(|f| !f.is_empty()) {
210	        Some(p) => memory::expand_home(p),
211	        None => cfg.path.as_deref().map(memory::expand_home).unwrap_or_else(memory::default_path),
212	    }
213	}
214	
215	fn emit<T: serde::Serialize>(json: bool, value: &T, text: impl FnOnce() -> String) -> Result<()> {
216	    if json {
217	        println!("{}", serde_json::to_string(value)?);
218	    } else {
219	        print!("{}", text());
220	    }
221	    Ok(())
222	}
223	
224	fn data_store(index: &Path, opts: CardOptions) -> Option<Store> {
225	    index.exists().then(|| Store::open(index, opts).ok()).flatten()
226	}
227	
228	pub fn run(
229	    cmd: MemoryCommand,
230	    path: &Path,
231	    cfg: &MemoryConfig,
232	    json: bool,
233	    index: &Path,
234	    card: CardOptions,
235	) -> Result<u8> {
236	    let settings = Settings::from_config(cfg);
237	    if let MemoryCommand::Briefing { ns, budget, format, remote, token_file, token_env } = &cmd {
238	        // A hook must never break the agent's session start.
239	        let text = match remote {
240	            Some(url) => remote_briefing(url, (token_file.as_deref(), token_env), ns.as_deref(), *budget),
241	            None => briefing(path, settings, ns.as_deref(), *budget, index, card),
242	        };
243	        return match text.and_then(|t| hook_output(&t, *format)) {
244	            Ok(text) => {
245	                print!("{text}");
246	                Ok(0)
247	            }
248	            Err(err) => {
249	                eprintln!("leviathan: briefing unavailable: {err:#}");
250	                Ok(0)
251	            }
252	        };
253	    }
254	    let mut m = Memory::open(path, settings)?;
255	    let now = leviathan::now_rfc3339();
256	    match cmd {
257	        MemoryCommand::Init => {
258	            let s = m.stats()?;
259	            emit(json, &s, || {
260	                format!(
261	                    "memory ready at {} ({} current)\n  next: `leviathan wrap <agent> --memory` prints the agent setup\n",
262	                    s.path.display(),
263	                    s.current
264	                )
265	            })?;
266	        }
267	        MemoryCommand::Remember {
268	            text,
269	            kind,
270	            subject,
271	            key,
272	            tags,
273	            importance,
274	            confidence,
275	            source,
276	            refs,
277	            pin,
278	            expires,
279	            aliases,
280	            ns,
281	        } => {
282	            let req = Remember {
283	                text: text.join(" "),
284	                kind,
285	                subject,
286	                key,
287	                tags,
288	                importance,
289	                confidence,
290	                source,
291	                refs,
292	                pinned: pin,
293	                expires,
294	                aliases,
295	                ns,
296	            };
297	            let out = m.remember(&req)?;
298	            emit(json, &out, || out.render())?;
299	        }
300	        MemoryCommand::Recall {
301	            words,
302	            subject,
303	            kind,
304	            ns,
305	            since,
306	            until,
307	            as_of,
308	            history,
309	            budget,
310	            limit,
311	            with_records,
312	        } => {
313	            let briefing = words.is_empty() && subject.is_none() && kind.is_empty();
314	            let req = RecallRequest {
315	                query: words.join(" "),
316	                ns,
317	                subject,
318	                kinds: kind,
319	                since,
320	                until,
321	                as_of,
322	                history,
323	                budget,
324	                limit,
325	                with_records,
326	                briefing,
327	            };
328	            let store = if with_records { data_store(index, card) } else { None };
329	            let out = m.recall(&req, store.as_ref())?;
330	            emit(json, &out, || out.render())?;
331	            if out.status != RecallStatus::Ok {
332	                return Ok(3);
333	            }
334	        }
335	        MemoryCommand::Briefing { .. } => unreachable!("handled above"),
336	        MemoryCommand::Forget { id, subject, key, ns, reason } => {
337	            let row = m.forget(&Forget { id, subject, key, ns, reason })?;
338	            emit(json, &row, || format!("forgot {}\n  {}\n", row.id, row.line(&now, false)))?;
339	        }
340	        MemoryCommand::List { ns, kind, subject, all, limit } => {
341	            let namespaces = m.read_namespaces(ns.as_deref())?;
342	            let rows = m.list(&namespaces, kind, subject.as_deref(), all, limit)?;
343	            emit(json, &rows, || {
344	                let mut out = format!("{} memories, newest first ({})\n", rows.len(), namespaces.join(", "));
345	                for r in &rows {
346	                    out.push_str(&r.line(&now, namespaces.len() > 1));
347	                    out.push('\n');
348	                }
349	                out
350	            })?;
351	        }
352	        MemoryCommand::History { id, subject, key, ns } => {
353	            let rows = m.history(id.as_deref(), subject.as_deref(), key.as_deref(), ns.as_deref())?;
354	            if rows.is_empty() {
355	                bail!("no memories in that slot");
356	            }
357	            emit(json, &rows, || rows.iter().map(|r| format!("{}\n", r.line(&now, false))).collect())?;
358	        }
359	        MemoryCommand::Stats => {
360	            let s = m.stats()?;
361	            emit(json, &s, || leviathan::render::memory_stats(&s))?;
362	        }
363	        MemoryCommand::Export { output } => {
364	            let n = if output == Path::new("-") {
365	                let mut out = std::io::stdout().lock();
366	                let n = m.export(&mut out)?;
367	                out.flush()?;
368	                n
369	            } else {
370	                let mut f = std::io::BufWriter::new(
371	                    std::fs::File::create(&output).with_context(|| format!("create {}", output.display()))?,
372	                );
373	                let n = m.export(&mut f)?;
374	                f.flush()?;
375	                n
376	            };
377	            eprintln!("exported {n} memories");
378	        }
379	        MemoryCommand::Import { path, markdown, ns } => {
380	            let mut text = String::new();
381	            if path == Path::new("-") {
382	                std::io::stdin().read_to_string(&mut text)?;
383	            } else {
384	                std::fs::File::open(&path)
385	                    .with_context(|| format!("open {}", path.display()))?
386	                    .read_to_string(&mut text)?;
387	            }
388	            let is_md = markdown || path.extension().is_some_and(|e| e.eq_ignore_ascii_case("md"));
389	            let report = if is_md {
390	                let source =
391	                    path.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or("stdin".into());
392	                m.import_markdown(&text, ns.as_deref(), &source)?
393	            } else {
394	                m.import_jsonl(BufReader::new(text.as_bytes()))?
395	            };
396	            emit(json, &report, || {
397	                let mut out = format!(
398	                    "imported {}: {} created, {} replaced, {} merged, {} skipped\n",
399	                    report.read, report.created, report.replaced, report.merged, report.skipped
400	                );
401	                for e in &report.errors {
402	                    out.push_str(&format!("  {e}\n"));
403	                }
404	                out
405	            })?;
406	        }
407	        MemoryCommand::Prune { forgotten, superseded, unused, dry_run } => {
408	            let r = m.prune(PruneOptions { forgotten, superseded, unused_days: unused, dry_run })?;
409	            emit(json, &r, || {
410	                format!(
411	                    "{}{} expired, {} forgotten, {} superseded removed; {} unused forgotten\n",
412	                    if r.dry_run { "dry run: " } else { "" },
413	                    r.expired,
414	                    r.forgotten,
415	                    r.superseded,
416	                    r.unused
417	                )
418	            })?;
419	        }
420	    }
421	    Ok(0)
422	}
423	
424	const EMPTY: &str = "Leviathan memory is empty. `remember` durable facts, preferences, decisions (with why) and \
425	    lessons as you learn them; give anything that can change a `key`. Never store secrets.\n";
426	
427	/// The briefing as text (`json` format: the full outcome as JSON).
428	fn briefing(
429	    path: &Path,
430	    settings: Settings,
431	    ns: Option<&str>,
432	    budget: Option<usize>,
433	    index: &Path,
434	    card: CardOptions,
435	) -> Result<String> {
436	    let mut m = Memory::open(path, settings)?;
437	    let store = data_store(index, card);
438	    let out = m.briefing(ns, budget, store.as_ref())?;
439	    Ok(if out.results.is_empty() { EMPTY.to_string() } else { out.render() })
440	}
441	
442	#[cfg(feature = "remote")]
443	fn remote_briefing(
444	    url: &str,
445	    token: (Option<&Path>, &str),
446	    ns: Option<&str>,
447	    budget: Option<usize>,
448	) -> Result<String> {
449	    let token = leviathan::http::client_token(token.0, token.1)?;
450	    let mut args = serde_json::json!({});
451	    if let Some(ns) = ns {
452	        args["ns"] = ns.into();
453	    }
454	    if let Some(b) = budget {
455	        args["budget"] = b.into();
456	    }
457	    let text = leviathan::http::call_tool(url, token.as_deref(), "recall", &args)?;
458	    Ok(if text.contains("0 of 0 current") { EMPTY.to_string() } else { text })
459	}
460	
461	#[cfg(not(feature = "remote"))]
462	fn remote_briefing(_: &str, _: (Option<&Path>, &str), _: Option<&str>, _: Option<usize>) -> Result<String> {
463	    bail!("this build has no `remote` feature")
464	}
465	
466	fn hook_output(text: &str, format: BriefingFormat) -> Result<String> {
467	    use serde_json::json;
468	    let session = |field: &str| json!({"hookSpecificOutput": {"hookEventName": "SessionStart", field: text}});
469	    let line = |v: serde_json::Value| format!("{v}\n");
470	    Ok(match format {
471	        BriefingFormat::Text => text.to_string(),
472	        BriefingFormat::Json => line(json!({"briefing": text})),
473	        BriefingFormat::Claude => line(session("additionalContext")),
474	        BriefingFormat::Gemini => line(json!({"hookSpecificOutput": {"additionalContext": text}})),
475	        BriefingFormat::Cursor => line(json!({"additional_context": text})),
476	        BriefingFormat::Copilot => line(json!({"additionalContext": text})),
477	        BriefingFormat::Cline => line(json!({"cancel": false, "contextModification": text})),
478	    })
479	}
